<?php require __DIR__.'/ui.php';role(['admin']);$p=db();$rows=$p->query("SELECT a.*,u.name user_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 500")->fetchAll();page_head('Auditoria');?><div class="card"><table><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>ID</th><th>IP</th></tr><?php foreach($rows as $x):?><tr><td><?=$x['created_at']?></td><td><?=e($x['user_name'])?></td><td><?=e($x['action'])?></td><td><?=e($x['entity'])?></td><td><?=$x['entity_id']?></td><td><?=e($x['ip'])?></td></tr><?php endforeach;?></table></div><?php page_foot();?>